(() => {
  const p = StudioPolicy,
    bindings = new Map(),
    windows = new Map(),
    requests = new Map();
  const ttl = 5 * 60 * 1000;
  let working = false;
  const autoJobs = new Map();
  let activeJob = null;
  let publicationError = "";
  const agent = createStudioBrowserAgent({ validBinding, validWindow, queue,
    publishing: () => Boolean(activeJob || [...autoJobs.values()].some((entry) => Date.parse(entry.job.scheduled_at) <= Date.now())) });
  // Files are updated by the existing helper. Reload only after every panel
  // connection is closed, so an update never discards active account grants.
  if (globalThis.StudioManagedInstallation === true)
    setInterval(async () => {
      if (working || windows.size || requests.size) return;
      try {
        const response = await fetch(
          browser.runtime.getURL("manifest.json") + "?update=" + Date.now(),
          { cache: "no-store" },
        );
        const next = await response.json();
        if (
          response.ok &&
          /^\d+\.\d+\.\d+$/.test(next.version) &&
          next.version !== browser.runtime.getManifest().version &&
          !working &&
          !windows.size &&
          !requests.size
        )
          browser.runtime.reload();
      } catch {
        /* The helper may be swapping the managed folder. Retry later. */
      }
    }, 30000);
  const popup = (s) =>
    s.id === browser.runtime.id &&
    s.url === browser.runtime.getURL("popup.html");
  function grantWindow(r) {
    const previous = windows.get(r.panelTab);
    const same =
      previous &&
      previous.userId === r.userId &&
      previous.companyId === r.target.companyId &&
      previous.windowId === r.windowId;
    if (!same) bindings.delete(r.panelTab);
    const window = {
      ...(same ? previous : {}),
      userId: r.userId,
      companyId: r.target.companyId,
      windowId: r.windowId,
    };
    windows.set(r.panelTab, window);
    return window;
  }
  async function workspaceChoices(r) {
    const tabs = (await browser.tabs.query({ windowId: r.windowId }))
      .filter((t) => t.id !== r.panelTab && !t.incognito && t.windowId === r.windowId);
    return r.targets.map((target) => {
      const choices = tabs.filter((t) => p.clean(t.url, target.platform) &&
        !/^(?:ads|adsmanager|business)\./i.test(new URL(t.url).hostname))
        .slice(0, 100).map((t) => ({ id: t.id, title: (t.title || "Sekme").slice(0, 150), url: p.clean(t.url, target.platform) }));
      const exact = choices.filter((t) => p.canonical(t.url, target.platform) === p.canonical(target.profileUrl, target.platform));
      const singleAccount = r.targets.filter((t) => t.platform === target.platform).length === 1;
      const current = bindings.get(r.panelTab)?.get(p.key(target));
      const suggestedTabId = choices.some((t) => t.id === current?.tabId) ? current.tabId
        : exact.length === 1 ? exact[0].id : singleAccount && choices.length === 1 ? choices[0].id : null;
      return { target, choices, suggestedTabId, identityLabel: current?.target.identityLabel || target.companyName };
    });
  }
  function cancelPreparation(panelTab) {
    for (const [id, r] of requests)
      if (r.panelTab === panelTab && r.action === "prepare")
        requests.delete(id);
    expire();
  }
  function expire() {
    for (const [id, r] of requests)
      if (Date.now() - r.at > ttl) requests.delete(id);
    browser.browserAction.setBadgeText({
      text: requests.size ? String(requests.size) : "",
    });
  }
  async function validBinding(sender, m) {
    const w = await validWindow(sender, m);
    const b = bindings.get(sender.tab.id)?.get(p.key(m));
    if (b && m.platform !== undefined && b.target.platform !== m.platform)
      throw new Error("Seçili platform bağlı hesapla eşleşmiyor.");
    if (
      !b ||
      b.userId !== m.userId ||
      b.target.companyId !== m.companyId ||
      b.target.accountId !== m.accountId
    )
      throw new Error(
        "Bu şirket/hesap için Firefox sekmesini yeniden bağlayın.",
      );
    const tab = await browser.tabs.get(b.tabId);
    if (
      tab.incognito ||
      tab.windowId !== w.windowId ||
      !p.clean(tab.url, b.target.platform)
    )
      throw new Error(
        "Seçili sekme bu hedefin sosyal ağına ait değil veya bağlı pencereden ayrıldı. İlgili şirket hesabını seçip sekmesini bağlayın.",
      );
    return b;
  }
  async function validWindow(sender, m) {
    const w = windows.get(sender.tab.id),
      tab = await browser.tabs.get(sender.tab.id);
    if (
      !w ||
      w.userId !== m.userId ||
      w.companyId !== m.companyId ||
      w.windowId !== tab.windowId ||
      tab.incognito
    )
      throw new Error(
        "Bu şirket için panelin bulunduğu Firefox penceresini bağlayın.",
      );
    return w;
  }
  async function page(b, action, extra = {}) {
    const tab = await browser.tabs.get(b.tabId);
    const panelTab = await browser.tabs.get(b.panelTab);
    if (
      tab.incognito ||
      tab.windowId !== b.windowId ||
      panelTab.windowId !== b.windowId ||
      !p.clean(tab.url, b.target.platform)
    )
      throw new Error(
        "Bu sayfa okunamaz. Yalnız bağlı penceredeki sosyal ağ kullanılır; giriş ve özel mesaj ekranları kapsam dışıdır.",
      );
    await browser.tabs.executeScript(b.tabId, {
      file: "advertising.js",
      frameId: 0,
    });
    await browser.tabs.executeScript(b.tabId, {
      file: "policy.js",
      frameId: 0,
    });
    await browser.tabs.executeScript(b.tabId, {
      file: "page-agent.js",
      frameId: 0,
    });
    return browser.tabs.sendMessage(
      b.tabId,
      { source: "studio-extension-agent", action, target: b.target, ...extra },
      { frameId: 0 },
    );
  }
  async function publicationAPI(entry, action, extra = {}) {
    const panel = await browser.tabs.get(entry.panelTab);
    const w = windows.get(entry.panelTab);
    if (
      !w ||
      w.companyId !== entry.companyId ||
      w.userId !== entry.userId ||
      panel.windowId !== entry.windowId ||
      w.windowId !== entry.windowId ||
      panel.incognito ||
      new URL(panel.url).origin !== p.panelOrigin
    )
      throw new Error("Yayın için onaylanan panel/pencere değişti.");
    const auth = await browser.tabs.sendMessage(
      entry.panelTab,
      { source: "studio-auth-check" },
      { frameId: 0 },
    );
    if (auth?.userId !== entry.userId || auth.companyId !== entry.companyId)
      throw new Error("Yayıncı yönetici oturumu değişti.");
    const result = await browser.tabs.sendMessage(
      entry.panelTab,
      {
        source: "studio-tab-publication",
        action,
        jobId: entry.job.id,
        executor: entry.executor,
        ...extra,
      },
      { frameId: 0 },
    );
    if (!result?.ok)
      throw new Error(result?.error || "Yayın işi doğrulanamadı.");
    return result.value;
  }
  async function publisher(entry, action, extra = {}) {
    const b = await validBinding(
      { tab: await browser.tabs.get(entry.panelTab) },
      {
        userId: entry.userId,
        companyId: entry.companyId,
        accountId: entry.job.account_id,
        platform: entry.job.snapshot.platform,
      },
    );
    if (
      b.tabId !== entry.tabId ||
      b.windowId !== entry.windowId ||
      JSON.stringify(b.target) !== JSON.stringify(entry.target)
    )
      throw new Error("Onaylanan hesap sekmesi değişti.");
    await browser.tabs.update(b.tabId, { active: true });
    for (const file of [
      "advertising.js",
      "policy.js",
      "publication-policy.js",
      "publisher.js",
    ])
      await browser.tabs.executeScript(b.tabId, { file, frameId: 0 });
    const result = await browser.tabs.sendMessage(
      b.tabId,
      {
        source: "studio-publisher-agent",
        action,
        target: b.target,
        job: entry.job,
        ...extra,
      },
      { frameId: 0 },
    );
    if (!result?.ok)
      throw new Error(result?.error || "Gönderi formu doğrulanamadı.");
    return result;
  }
  async function drainPublications() {
    if (agent.anyActive()) return;
    if (working) return;
    const entry = [...autoJobs.values()].find(
      (e) => Date.parse(e.job.scheduled_at) <= Date.now(),
    );
    if (!entry) return;
    working = true;
    activeJob = entry.job.id;
    publicationError = "";
    autoJobs.delete(entry.job.id);
    let claimed = false,
      sending = false;
    try {
      const key = "publication:" + entry.job.id;
      const journal = await browser.storage.local.get(key);
      if (journal[key])
        throw new Error(
          "Bu iş daha önce yürütmeye alındı; otomatik tekrar yapılmaz.",
        );
      entry.job = await publicationAPI(entry, "claim");
      claimed = true;
      // Durable before any DOM changes. A restart cannot replay a possibly sent job.
      await browser.storage.local.set({
        [key]: { at: Date.now(), state: "started" },
      });
      const images = [];
      for (let i = 0; i < entry.job.snapshot.media.length; i++)
        images.push(await publicationAPI(entry, "media", { index: i }));
      const ready = await publisher(entry, "prepare", { images });
      if (!ready.ready || !ready.sessionId)
        throw new Error("Yayın önizlemesi doğrulanamadı.");
      await publicationAPI(entry, "sending");
      sending = true;
      // Session/account/window checks run again immediately before the click.
      const result = await publisher(entry, "publish", {
        sessionId: ready.sessionId,
      });
      await publicationAPI(entry, "result", {
        state: result.state === "verified" ? "verified" : "unknown",
        url: result.url,
      });
      await browser.storage.local.set({
        [key]: { at: Date.now(), state: result.state },
      });
    } catch (e) {
      publicationError = e.message || "Yayın tamamlanamadı.";
      if (claimed)
        await publicationAPI(entry, "result", {
          state: sending ? "unknown" : "failed",
          detail: publicationError.slice(0, 300),
        }).catch(() => {});
    } finally {
      activeJob = null;
      working = false;
      // Journal metadata only: no tokens, texts, images or account details.
      try {
        const all = await browser.storage.local.get(null);
        const keys = Object.keys(all)
          .filter((k) => k.startsWith("publication:"))
          .sort((a, b) => (all[b].at || 0) - (all[a].at || 0));
