  function queue(r) {
    for (const [id, old] of requests)
      if (old.panelTab === r.panelTab) requests.delete(id);
    if (requests.size >= 5)
      throw new Error("Bekleyen eklenti isteklerini tamamlayın.");
    const id = crypto.randomUUID();
