    windows.delete(tabId);
    for (const [id, accounts] of bindings) {
      for (const [accountId, b] of accounts)
        if (b.tabId === tabId) accounts.delete(accountId);
      if (!accounts.size) bindings.delete(id);
    }
    for (const [id, r] of requests)
