    (async () => {
      expire();
      if (!m || typeof m.action !== "string")
        throw new Error("Geçersiz eklenti isteği.");
      if (popup(sender)) {
        if (m.action === "popup-state") {
          return {
            requests: await Promise.all(
              [...requests.values()].map(async (r) => {
                const tabs =
                  r.action === "connect"
                    ? await browser.tabs.query({ windowId: r.windowId })
                    : [];
                return {
                  ...r,
                  ...(r.action === "connect-workspace" ? { accounts: await workspaceChoices(r) } : {}),
                  choices: tabs
                    .filter(
                      (t) =>
                        t.id !== r.panelTab &&
                        !t.incognito &&
                        t.windowId === r.windowId &&
                        p.clean(t.url, r.target.platform),
                    )
                    .slice(0, 100)
                    .map((t) => ({
                      id: t.id,
                      title: (t.title || "Sekme").slice(0, 150),
                      url: p.clean(t.url, r.target.platform),
                      pinned: t.pinned,
                    })),
                };
              }),
            ),
            count: windows.size,
          };
        }
        if (m.action === "revoke") {
          agent.clear();
          bindings.clear();
          autoJobs.clear();
          windows.clear();
          requests.clear();
          expire();
          return {};
        }
        const r = requests.get(m.id);
        if (!r)
          throw new Error("İstek süresi doldu. Panelden yeniden başlatın.");
        if (m.action === "reject") {
          requests.delete(m.id);
          expire();
          return {};
        }
        if (m.action !== "approve" || working)
          throw new Error("Eklenti işlemi devam ediyor.");
        working = true;
        try {
          const panelTab = await browser.tabs.get(r.panelTab);
          if (
            panelTab.incognito ||
            panelTab.windowId !== r.windowId ||
            new URL(panelTab.url).origin !== p.panelOrigin
          )
            throw new Error("Panel sekmesi veya penceresi değişti.");
          // Recheck the real panel session immediately before granting access or writing.
          const auth = await browser.tabs.sendMessage(
            r.panelTab,
            { source: "studio-auth-check" },
            { frameId: 0 },
          );
          if (auth?.userId !== r.userId)
            throw new Error("Panel oturumu değişti; yeniden bağlayın.");
          if (r.action === "agent-start") {
            await agent.approve(r);
          } else if (r.action === "connect-workspace") {
            if (auth.companyId !== r.target.companyId)
              throw new Error("Seçili şirket değişti; yeniden bağlayın.");
            if (!Array.isArray(m.selections) || !m.selections.length || m.selections.length > r.targets.length ||
              new Set(m.selections.map((s) => s.accountId)).size !== m.selections.length ||
              new Set(m.selections.map((s) => s.tabId)).size !== m.selections.length)
              throw new Error("Her hesap için farklı bir sekme seçin.");
            const candidates = await workspaceChoices(r);
            const approved = [];
            for (const selection of m.selections) {
              const row = candidates.find((c) => c.target.accountId === selection.accountId);
              if (!row || !row.choices.some((t) => t.id === selection.tabId) ||
                typeof selection.identityLabel !== "string" || !selection.identityLabel.trim() || selection.identityLabel.length > 100)
                throw new Error("Hesap sekmesi veya görünen sayfa adı doğrulanamadı. Listeyi yenileyin.");
              approved.push({ userId: r.userId, target: p.target({ ...row.target, identityLabel: selection.identityLabel }),
                tabId: selection.tabId, windowId: r.windowId, panelTab: r.panelTab });
            }
            const w = grantWindow(r), accounts = bindings.get(r.panelTab) || new Map();
            for (const b of approved) accounts.set(p.key(b.target), b);
            bindings.set(r.panelTab, accounts);
            if (!accounts.has(w.activeAccountId)) w.activeAccountId = p.key(approved[0].target);
          } else if (r.action === "publish-batch") {
            for (const entry of r.entries) {
              await validBinding(
                { tab: panelTab },
                {
                  userId: r.userId,
                  companyId: entry.companyId,
                  accountId: entry.job.account_id,
                  platform: entry.job.snapshot.platform,
                },
              );
              const current = await publicationAPI(entry, "get");
              if (
                current.fingerprint !== entry.job.fingerprint ||
                JSON.stringify(current.snapshot) !==
                  JSON.stringify(entry.job.snapshot)
              )
                throw new Error("Yayın önizlemesi değişti; yeniden inceleyin.");
            }
            let approved = 0;
            const failures = [];
            for (const entry of [...r.entries]) {
              try {
                entry.job = await publicationAPI(entry, "authorize");
                // Preserve each successful authorization before trying the next
                // target. A later failure must not strand already queued jobs.
                autoJobs.set(entry.job.id, entry);
                r.entries = r.entries.filter((e) => e.job.id !== entry.job.id);
                approved++;
              } catch (e) {
                failures.push(`${entry.target.platform}: ${e.message || "Onay tamamlanamadı."}`);
              }
            }
            publicationError = failures.length
              ? `${approved} hedef yayın sırasına alındı; ${failures.length} hedef onaylanamadı. ${failures.join(" ")}`.slice(0, 1000)
              : "";
            r.error = publicationError;
            if (failures.length) throw new Error(publicationError);
          } else if (r.action === "connect-window") {
            grantWindow(r);
          } else if (r.action === "connect") {
            const tab = await browser.tabs.get(m.tabId);
            if (
              tab.incognito ||
              tab.windowId !== r.windowId ||
              !p.clean(tab.url, r.target.platform) ||
              tab.id === r.panelTab
            )
              throw new Error(
                "Panelin bulunduğu pencereden uygun bir sosyal medya sekmesi seçin.",
              );
            if (
              p.advertising(r.target.platform) &&
              !/^[a-z0-9-]{3,50}$/i.test(m.identityId || "")
            )
              throw new Error("Panelde görünen reklam hesabı kimliğini girin.");
            if (
              typeof m.identityLabel !== "string" ||
              !m.identityLabel.trim() ||
              m.identityLabel.length > 100
            )
              throw new Error(
                "Hedef sayfanın ekranda görünen tam adını girin.",
              );
            const w = grantWindow(r);
            const accounts = bindings.get(r.panelTab) || new Map();
            accounts.set(p.key(r.target), {
              userId: r.userId,
              target: p.target({
                ...r.target,
                identityLabel: m.identityLabel,
                identityId: m.identityId,
              }),
              tabId: tab.id,
              windowId: r.windowId,
              panelTab: r.panelTab,
            });
            bindings.set(r.panelTab, accounts);
            w.activeAccountId = p.key(r.target);
          } else {
            const b = bindings.get(r.panelTab)?.get(p.key(r.target));
            if (
              !b ||
              b.userId !== r.userId ||
              b.tabId !== r.tabId ||
              JSON.stringify(b.target) !== JSON.stringify(r.target)
            )
              throw new Error("Hedef hesap değişti.");
            const result = await page(b, "fill", {
              snapshotId: r.snapshotId,
              text: r.text,
              elementId: r.elementId,
            });
            if (!result.ok) throw new Error(result.error);
          }
          requests.delete(m.id);
          expire();
          return {};
        } catch (e) {
          if (r.action === "publish-batch") r.error = (e.message || "Yayın onayı tamamlanamadı.").slice(0, 1000);
          throw e;
        } finally {
          working = false;
        }
      }
      if (!p.panel(sender))
        throw new Error("Yalnız Sosyal Studio paneli bağlantı kurabilir.");
      if (m.action === "disconnect") {
        agent.stop(sender.tab.id);
        for (const [id, e] of autoJobs)
          if (e.panelTab === sender.tab.id) autoJobs.delete(id);
        bindings.delete(sender.tab.id);
        windows.delete(sender.tab.id);
        for (const [id, r] of requests)
          if (r.panelTab === sender.tab.id) requests.delete(id);
        expire();
        return {};
      }
      if (typeof m.userId !== "string" || m.userId.length > 100)
        throw new Error("Panel oturumu doğrulanamadı.");
      if (["agent-start", "agent-stop", "agent-observe", "agent-act"].includes(m.action)) {
        if (m.action === "agent-stop") {
          for (const [id, r] of requests) if (r.panelTab === sender.tab.id && r.action === "agent-start" && r.runId === m.sessionId) requests.delete(id);
          expire();
        }
        if (m.action === "agent-start" && [...requests.values()].some((r) => r.panelTab === sender.tab.id && r.action !== "agent-start"))
          throw new Error("Önce Firefox simgesindeki bekleyen bağlantı/yayın isteğini tamamlayın.");
        return agent.handle(m, sender);
      }
      if (m.action === "status") {
        const w = windows.get(sender.tab.id),
          current = await browser.tabs.get(sender.tab.id);
        if (w && m.companyId && w.companyId !== m.companyId) agent.stop(sender.tab.id);
        if (w && (w.userId !== m.userId || w.windowId !== current.windowId)) {
          agent.stop(sender.tab.id);
          bindings.delete(sender.tab.id);
          windows.delete(sender.tab.id);
          throw new Error(
            "Panel hesabı veya penceresi değişti; yeniden bağlayın.",
          );
        }
        const accounts = bindings.get(sender.tab.id);
        const b = accounts?.get(w?.activeAccountId);
        return {
          version: browser.runtime.getManifest().version,
          window: w ? { companyId: w.companyId, windowId: w.windowId } : null,
          bindings: [...(accounts?.values() || [])].map((b) => ({
            ...b.target,
            tabId: b.tabId,
          })),
          binding: b ? { ...b.target, tabId: b.tabId } : null,
          publishing: {
            activeJob,
            queued: [...autoJobs.keys()],
            error: [...requests.values()].find((r) => r.panelTab === sender.tab.id && r.userId === m.userId && r.error)?.error || publicationError,
            pendingJobs: [...requests.values()]
              .filter((r) => r.panelTab === sender.tab.id && r.action === "publish-batch" && r.userId === m.userId)
              .flatMap((r) => r.entries.map((e) => e.job.id)),
          },
          pending: [...requests.values()].some(
            (r) => r.panelTab === sender.tab.id,
          ),
          agent: agent.summary(sender.tab.id),
        };
      }
      if (m.action === "publish-batch") {
        if (agent.anyActive()) throw new Error("Yayın kuyruğunu başlatmadan önce Qwen Firefox görevini durdurun.");
        const w = await validWindow(sender, m);
        if (
          !Array.isArray(m.jobs) ||
          !m.jobs.length ||
          m.jobs.length > 20 ||
          new Set(m.jobs.map((j) => j.id)).size !== m.jobs.length
        )
          throw new Error("En fazla 20 farklı hedef yayını seçin.");
        const entries = [];
        for (const job of m.jobs) {
          if (
            job.company_id !== m.companyId ||
            job.created_by !== m.userId ||
            job.snapshot?.transport !== "firefox-tabs" ||
            !["draft", "queued"].includes(job.state)
          )
            throw new Error(
              "Yayın işi seçili şirket/yöneticiye ait değil veya yürütmeye alınmış.",
            );
          const b = await validBinding(sender, {
            ...m,
            accountId: job.account_id,
            platform: job.snapshot.platform,
          });
          if (
            b.target.profileUrl !== job.snapshot.profileUrl ||
            b.target.identityLabel !== job.snapshot.identityLabel
          )
            throw new Error(
              "Hedef profil/sayfa adı eklentideki onayla eşleşmiyor.",
            );
          entries.push({
            job,
            target: b.target,
            tabId: b.tabId,
            panelTab: sender.tab.id,
            windowId: w.windowId,
            userId: m.userId,
            companyId: m.companyId,
            executor: crypto.randomUUID(),
          });
        }
        return queue({
          action: "publish-batch",
          target: { companyId: m.companyId, companyName: m.companyName },
          userId: m.userId,
          panelTab: sender.tab.id,
          windowId: w.windowId,
          entries,
        });
      }
      if (m.action === "open-ad-portal") {
        const target = p.target(m.target),
          provider = p.advertising(target.platform);
        if (!provider) throw new Error("Reklam paneli seçin.");
        const w = await validWindow(sender, {
          ...m,
          companyId: target.companyId,
        });
        const tab = await browser.tabs.create({
          windowId: w.windowId,
          url: provider.home,
          active: true,
        });
        return { tabId: tab.id };
      }
      if (m.action === "connect" || m.action === "connect-window" || m.action === "connect-workspace") {
        let target;
        if (m.action === "connect") target = p.target(m.target);
        else {
          if (
            !/^[a-f0-9-]{36}$/i.test(m.companyId || "") ||
            typeof m.companyName !== "string" ||
            m.companyName.length > 150
          )
            throw new Error("Şirket seçin.");
          target = { companyId: m.companyId, companyName: m.companyName };
        }
        const tab = await browser.tabs.get(sender.tab.id);
        let targets;
        if (m.action === "connect-workspace") {
          if (!Array.isArray(m.targets) || !m.targets.length || m.targets.length > 25)
            throw new Error("Hesap bağlantılarında en az bir hedef profil adresi kaydedin (en fazla 25).");
          targets = m.targets.map((t) => p.target(t));
          if (targets.some((t) => t.companyId !== target.companyId || p.advertising(t.platform)) ||
            new Set(targets.map((t) => t.accountId)).size !== targets.length)
            throw new Error("Şirket hesapları doğrulanamadı.");
        }
        return queue({
          action: m.action,
          target,
          ...(targets ? { targets } : {}),
          userId: m.userId,
          panelTab: sender.tab.id,
          windowId: tab.windowId,
        });
      }
      if (m.action === "tabs" || m.action === "select-tab") {
        const w = await validWindow(sender, m);
        if (m.action === "select-tab") {
          if (!Number.isInteger(m.tabId)) throw new Error("Bir sekme seçin.");
          const tab = await browser.tabs.get(m.tabId);
          if (tab.incognito || tab.windowId !== w.windowId)
            throw new Error("Başka Firefox penceresine erişilemez.");
          await browser.tabs.update(tab.id, { active: true });
          const matching = [
            ...(bindings.get(sender.tab.id)?.values() || []),
          ].filter((b) => b.tabId === tab.id);
          w.activeAccountId =
            matching.length === 1 ? p.key(matching[0].target) : null;
          cancelPreparation(sender.tab.id);
        }
        const tabs = (await browser.tabs.query({ windowId: w.windowId }))
          .filter((t) => !t.incognito && t.windowId === w.windowId)
          .sort((a, b) => a.index - b.index);
        return {
          tabs: tabs.map((t) => {
            let url = "";
            try {
              const u = new URL(t.url);
              url =
                u.protocol === "https:" || u.protocol === "http:"
                  ? u.origin + u.pathname
                  : u.protocol;
            } catch {
              /* internal */
            }
            return {
              id: t.id,
              title: (t.title || "Sekme").slice(0, 150),
              url: url.slice(0, 400),
              active: t.active,
              pinned: t.pinned,
              panel: t.id === sender.tab.id,
            };
          }),
        };
      }
      if (m.action === "select-target") {
        const b = await validBinding(sender, m);
        const w = await validWindow(sender, m);
        w.activeAccountId = p.key(b.target);
        cancelPreparation(sender.tab.id);
        return {};
      }
      const b = await validBinding(sender, m);
      if (m.action === "read") {
        const result = await page(b, "read");
        if (!result.ok) throw new Error(result.error);
        return { page: result.page };
      }
      if (m.action === "focus") {
        await browser.tabs.update(b.tabId, { active: true });
        return {};
      }
      if (m.action === "prepare") {
        if (
          typeof m.text !== "string" ||
          !m.text.trim() ||
          m.text.length > 10000 ||
          typeof m.snapshotId !== "string" ||
          m.snapshotId.length > 64
        )
          throw new Error("Önce sekmeyi okuyun ve bir taslak seçin.");
        return queue({
          action: "prepare",
          target: b.target,
          userId: m.userId,
          panelTab: sender.tab.id,
          windowId: b.windowId,
          tabId: b.tabId,
          snapshotId: m.snapshotId,
          text: m.text,
          elementId: m.elementId,
        });
      }
      throw new Error("Bu işlem desteklenmiyor.");
    })()
      .then((value) => ({ ok: true, ...value }))
      .catch((e) => ({
        ok: false,
        error: e.message || "Eklenti işlemi tamamlanamadı.",
      })),
  );
})();

files.panel-bridge.js:
(() => {
  if (window !== window.top) return;
  const source = "sosyal-studio-panel-v1",
    reply = "sosyal-studio-firefox-v1";
  let pending = 0;
  browser.runtime.onMessage.addListener((m, sender) => {
    if (sender.id !== browser.runtime.id || m?.source !== "studio-auth-check")
      return;
    return fetch(location.origin + "/api/auth/me", {
      credentials: "include",
      cache: "no-store",
      redirect: "error",
    })
      .then(async (r) => {
        const a = r.ok ? await r.json() : null;
        return {
          userId: a?.user?.role === "admin" ? a.user.id : null,
          companyId: new URL(location.href).searchParams.get("company"),
        };
      })
      .catch(() => ({ userId: null }));
  });
  browser.runtime.onMessage.addListener((m, sender) => {
    if (
      sender.id !== browser.runtime.id ||
      m?.source !== "studio-tab-publication"
    )
      return;
    return (async () => {
      if (
        !/^[a-f0-9-]{36}$/i.test(m.jobId || "") ||
        !["get", "media", "authorize", "claim", "sending", "result"].includes(
          m.action,
        )
      )
        throw new Error("Geçersiz yayın isteği.");
      let path = "/api/tab-publications/" + m.jobId;
      if (m.action === "media") {
        if (!Number.isInteger(m.index) || m.index < 0 || m.index > 9)
          throw new Error("Görsel sırası geçersiz.");
        path += "/media/" + m.index;
      } else if (m.action !== "get") path += "/" + m.action;
      const write = !["get", "media"].includes(m.action);
      const r = await fetch(location.origin + path, {
        credentials: "include",
        cache: "no-store",
        redirect: "error",
        ...(write
          ? {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                executor: m.executor,
                confirmed: true,
                state: m.state,
                url: m.url,
                detail: m.detail,
              }),
            }
          : {}),
      });
      const value = await r.json();
      if (!r.ok) throw new Error(value.error || "Yayın adımı reddedildi.");
      return { ok: true, value };
    })().catch((e) => ({ ok: false, error: e.message }));
  });
  window.addEventListener("message", async (event) => {
    const m = event.data;
    if (
      event.source !== window ||
      event.origin !== location.origin ||
      m?.source !== source ||
      typeof m.id !== "string" ||
      m.id.length > 64 ||
      ![
        "status",
        "agent-start",
        "agent-stop",
        "agent-observe",
        "agent-act",
        "publish-batch",
        "connect",
        "open-ad-portal",
        "connect-window",
        "connect-workspace",
        "tabs",
        "select-tab",
        "select-target",
        "read",
        "focus",
        "prepare",
        "disconnect",
      ].includes(m.action) ||
      JSON.stringify(m).length > 16000 ||
      pending >= 3
    )
      return;
    pending++;
    try {
      const response = await fetch(location.origin + "/api/auth/me", {
        credentials: "include",
        cache: "no-store",
        redirect: "error",
      });
      const auth = response.ok ? await response.json() : null;
      if (auth?.user?.role !== "admin" || typeof auth.user.id !== "string") {
        await browser.runtime
          .sendMessage({ action: "disconnect" })
          .catch(() => {});
        throw new Error(
          "Firefox bağlantısı için panelde yönetici olarak giriş yapın.",
        );
      }
      let jobs;
      if (m.action === "publish-batch") {
        if (
          !Array.isArray(m.jobIds) ||
          !m.jobIds.length ||
          m.jobIds.length > 20 ||
          m.jobIds.some((id) => !/^[a-f0-9-]{36}$/i.test(id))
        )
          throw new Error("Yayın işlerini seçin.");
        jobs = await Promise.all(
          m.jobIds.map(async (id) => {
            const r = await fetch(
              location.origin + "/api/tab-publications/" + id,
              { credentials: "include", cache: "no-store", redirect: "error" },
            );
            const value = await r.json();
            if (!r.ok)
              throw new Error(value.error || "Yayın önizlemesi doğrulanamadı.");
            return value;
          }),
        );
      }
      let target, targets;
      if (m.action === "agent-start") {
        const companyId = new URL(location.href).searchParams.get("company");
        if (companyId !== m.companyId || !Array.isArray(m.targets) || !m.targets.length || m.targets.length > 25)
          throw new Error("Seçili şirketin bağlı hesaplarını belirtin.");
        const res = await fetch(location.origin + "/api/social/accounts?" + new URLSearchParams({ companyId }),
          { credentials: "include", cache: "no-store", redirect: "error" });
        if (!res.ok) throw new Error("Görev hesapları doğrulanamadı.");
        const accounts = await res.json();
        targets = m.targets.map((t) => {
          const account = accounts.find((a) => a.id === t.accountId && a.companyId === companyId);
          const ad = (globalThis.StudioAdvertising || []).find((p) => "ads-" + p.id === t.platform && p.platforms.includes(account?.platform));
          if (!account || (account.platform !== t.platform && !ad)) throw new Error("Görev hedefi seçili şirketin kayıtlı hesabı değil.");
          return { accountId: account.id, platform: t.platform };
        });
      }
      if (m.action === "connect-workspace") {
        const companyId = new URL(location.href).searchParams.get("company");
        if (companyId !== m.companyId)
          throw new Error("Paneldeki seçili şirket değişti. Yeniden deneyin.");
        const res = await fetch(
          location.origin + "/api/social/accounts?" + new URLSearchParams({ companyId }),
          { credentials: "include", cache: "no-store", redirect: "error" },
        );
        if (!res.ok) throw new Error("Şirket hesapları doğrulanamadı.");
        const accounts = await res.json();
        targets = accounts.filter((a) => a.companyId === companyId && a.profileUrl)
          .map((a) => ({ ...a, accountId: a.id, companyName: String(m.companyName || "").slice(0, 150) }));
      }
      if (m.action === "connect" || m.action === "open-ad-portal") {
        const params = new URLSearchParams({
          companyId: m.target?.companyId || "",
        });
        const res = await fetch(
          location.origin + "/api/social/accounts?" + params,
          { credentials: "include", cache: "no-store", redirect: "error" },
        );
        if (!res.ok) throw new Error("Şirket hesapları doğrulanamadı.");
        const accounts = await res.json();
        const account = accounts.find(
          (a) =>
            a.id === m.target?.accountId && a.companyId === m.target?.companyId,
        );
        if (!account) throw new Error("Hesap seçili şirkete ait değil.");
        target = {
          ...account,
          accountId: account.id,
          companyName: String(m.target?.companyName || "").slice(0, 150),
        };
        if (m.target?.adProvider) {
          const provider = (globalThis.StudioAdvertising || []).find(
            (p) =>
              p.id === m.target.adProvider &&
              p.platforms.includes(account.platform),
          );
          if (!provider)
            throw new Error(
              "Bu reklam paneli kayıtlı hesabın platformuyla eşleşmiyor.",
            );
          target = {
            ...target,
            platform: "ads-" + provider.id,
            profileUrl: provider.home,
          };
        }
      }
      const result = await browser.runtime.sendMessage({
        action: m.action,
        jobs,
        userId: auth.user.id,
        target,
        targets,
        task: m.task,
        sessionId: m.sessionId,
        requestId: m.requestId,
        decision: m.decision,
        companyName: m.companyName,
        tabId: m.tabId,
        text: m.text,
        snapshotId: m.snapshotId,
        companyId: m.action === "status" ? new URL(location.href).searchParams.get("company") : m.companyId,
        accountId: m.accountId,
        platform: m.platform,
        elementId: m.elementId,
      });
      window.postMessage(
        { source: reply, id: m.id, ...result },
        location.origin,
      );
    } catch (e) {
      window.postMessage(
        {
          source: reply,
          id: m.id,
          ok: false,
          error: e.message || "Firefox eklentisiyle bağlantı kurulamadı.",
        },
        location.origin,
      );
    } finally {
      pending--;
    }
  });
})();

files.page-agent.js:
(() => {
  if (globalThis.__studioPageAgent) return;
  globalThis.__studioPageAgent = true;
  let snapshot;
  const p = StudioPolicy;
  const norm = (v) =>
