      Math.floor(r.x * canvas.width / o.width) - 2, Math.floor(r.y * canvas.height / o.height) - 2,
      Math.ceil(r.width * canvas.width / o.width) + 4, Math.ceil(r.height * canvas.height / o.height) + 4,
