        const url = policy.safeURL(result.navigate, b.target.platform);
        if (!url) throw new Error("Sayfa bağlantısı sosyal medya kapsamı dışında.");
        if (!sessions.has(s.panelTab)) throw new Error("Firefox görevi durduruldu.");
